use std::thread;

fn main() {
    let data = [1, 2, 3, 4, 5];
    let (left, right) = data.split_at(2);
    let (a, b) = thread::scope(|s| {
        let h1 = s.spawn(|| left.iter().sum::<i32>());
        let h2 = s.spawn(|| right.iter().sum::<i32>());
        (h1.join().unwrap(), h2.join().unwrap())
    });
    println!("{a} {b} {}", a + b);
}

use std::thread;

fn main() {
    let lines = vec!["a b", "b c"];
    let h = thread::spawn(|| {
        println!("{}", lines.len());
    });
    h.join().unwrap();
}

fn main() {
    let mut pairs = vec![("x", 1), ("y", 3), ("a", 3)];
    pairs.sort_by(|p, q| q.1.cmp(&p.1).then(p.0.cmp(q.0)));
    println!("{pairs:?}");
}

use std::collections::HashMap;

fn main() {
    let mut map: HashMap<String, usize> = HashMap::new();
    for w in "Hi hi! HI.".split_whitespace() {
        let w = w.trim_matches(|c: char| !c.is_alphanumeric()).to_lowercase();
        *map.entry(w).or_insert(0) += 1;
    }
    println!("{} {:?}", map.len(), map.get("hi"));
}

fn main() {
    let lines: Vec<u32> = (1..=10).collect();
    let threads = 4;
    let size = lines.len().div_ceil(threads);
    let lens: Vec<usize> = lines.chunks(size).map(|c| c.len()).collect();
    println!("{size} {lens:?}");
}
